import java.util.*;
public class Divisibleby5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc=new Scanner(System.in);
		int num=sc.nextInt();
		if(num % 5 ==0) {
			System.out.println(" Is the number "+num+" is divisble by 5 ? true");
		}
		else {
			System.out.println( " Is the number " +num+ "  is by divisble by 5 ? false");
		}

	}

}
